function layer(content,cls="drawer"){$("#layer").innerHTML=`<div class="overlay" id="overlay"><section class="${cls}" role="dialog" aria-modal="true">${content}</section></div>`;$("#overlay").onclick=e=>{if(e.target.id==="overlay")closeLayer()}}
function acaiGroup(option){const name=String(state.detail?.name||"");if(name.startsWith("Monte seu pote"))return {name:"Complementos grátis",limit:5};if(name.startsWith("Copo trufado")||name.startsWith("Açaí na garrafa"))return {name:"Escolha seu sabor",limit:1};const fruit=["Banana","Manga","Morango","Kiwi"],extras=["Creme de ninho da casa","Creme de oreo da casa","Creme de café","Cupuaçu"];return fruit.includes(option.name)?{name:"Frutas",limit:2}:extras.includes(option.name)?{name:"Extras",limit:3}:{name:"Complementos doces",limit:2}}
function complementGroups(options){const groups=[{title:"Frutas",text:"Escolha até 2 itens",names:["Banana","Manga","Morango","Kiwi"]},{title:"Extras",text:"Escolha até 3 itens",names:["Creme de ninho da casa","Creme de oreo da casa","Creme de café","Cupuaçu"]},{title:"Complementos doces",text:"Escolha até 2 itens",names:[]}];const row=(option,index)=>`<div class="complement-row"><div><strong>${esc(option.name)}</strong><small>${option.price_cents?`+ ${money(option.price_cents)}`:"Sem custo adicional"}</small></div><div class="stepper"><button type="button" data-addon-q="-1" data-addon-index="${index}">−</button><span data-addon-value="${index}">0</span><button type="button" data-addon-q="1" data-addon-index="${index}">+</button></div></div>`;const used=new Set;return groups.map((group,g)=>{const entries=options.map((option,index)=>({option,index})).filter(({option})=>g===2?!groups.slice(0,2).some(x=>x.names.includes(option.name)):group.names.includes(option.name));entries.forEach(({index})=>used.add(index));return entries.length?`<div class="panel-head"><div><strong>${group.title}</strong><div class="muted">${group.text}</div></div></div>${entries.map(({option,index})=>row(option,index)).join("")}`:""}).join("")+options.map((option,index)=>used.has(index)?"":row(option,index)).join("")}
function openProduct(id,cart=state.cart,onAdded=null){const p=state.catalog.products.find(x=>x.id===id);if(!p||!p.is_available)return;state.detail=p;state.detailQty=1;const options=(p.complements||[]).map(option=>({...option,quantity:0})),flavorIncludedInBasePrice=[1,2,10,11].includes(Number(p.id)),price=()=>flavorIncludedInBasePrice?p.price_cents:p.price_cents+options.reduce((sum,option)=>sum+option.price_cents*option.quantity,0);layer(`<div class="drawer-header"><button class="icon-btn" data-close>←</button><h2>PRODUTO</h2></div><div class="detail-body"><h2>${esc(p.name)}</h2><div class="muted">${esc(p.description)}</div>${options.length?`<section class="complements-panel">${complementGroups(options)}</section>`:""}</div><div class="detail-action"><div class="stepper"><button data-q="-1">−</button><span id="detail-qty">1</span><button data-q="1">+</button></div><button class="primary-btn" id="detail-add">Adicionar • <span id="detail-total">${money(p.price_cents)}</span></button></div>`,"product-detail");const refresh=()=>{$("#detail-qty").textContent=state.detailQty;$("#detail-total").textContent=money(price()*state.detailQty)};document.querySelector("[data-close]").onclick=closeLayer;document.querySelectorAll("[data-q]").forEach(b=>b.onclick=()=>{state.detailQty=Math.max(1,Math.min(20,state.detailQty+Number(b.dataset.q)));refresh()});document.querySelectorAll("[data-addon-q]").forEach(b=>b.onclick=()=>{const option=options[Number(b.dataset.addonIndex)],delta=Number(b.dataset.addonQ),group=acaiGroup(option),selected=options.filter(item=>acaiGroup(item).name===group.name).reduce((sum,item)=>sum+item.quantity,0);if(delta>0&&selected>=group.limit)return toast(`${group.name}: limite de ${group.limit} itens`);option.quantity=Math.max(0,Math.min(option.max_quantity,option.quantity+delta));document.querySelector(`[data-addon-value="${b.dataset.addonIndex}"]`).textContent=option.quantity;refresh()});$("#detail-add").onclick=()=>{addItem(p,state.detailQty,cart,options.map(({name,price_cents,quantity})=>({name,price_cents,quantity})).filter(option=>option.quantity));updateCartBadges();closeLayer();if(onAdded)onAdded();toast("Produto adicionado")}}
function updateCartBadges(){document.querySelectorAll("#cart-count").forEach(x=>x.textContent=cartCount())}
function cartItemsMarkup(cart=state.cart){return cart.map(i=>`<div class="cart-item"><img src="${esc(i.product.image_url)}" alt=""><div><div class="cart-name">${esc(i.product.name)}</div>${i.complements?.length?`<div class="cart-addons">${i.complements.map(option=>`+ ${option.quantity}× ${esc(option.name)}`).join("<br>")}</div>`:""}${i.notes?`<div class="cart-note">Obs.: ${esc(i.notes)}</div>`:""}<div class="muted">${money(itemUnitPrice(i)*i.quantity)}</div></div><div class="stepper"><button data-cart-q="-1" data-id="${i.product.id}" data-key="${esc(i.key||i.product.id)}">−</button><span>${i.quantity}</span><button data-cart-q="1" data-id="${i.product.id}" data-key="${esc(i.key||i.product.id)}">+</button></div></div>`).join("")}
function openCart(){layer(`<div class="drawer-header"><button class="icon-btn" data-close>←</button><h2>Sua sacola</h2><button type="button" class="text-danger-btn" id="clear-cart" ${state.cart.length?"":"disabled"}>Limpar</button></div><div class="drawer-content" id="cart-body">${state.cart.length?cartItemsMarkup():'<div class="empty">Sua sacola está vazia.</div>'}</div><div class="drawer-footer"><div class="cart-total"><span>Total</span><span id="cart-total">${money(cartTotal())}</span></div><button class="primary-btn full" id="checkout" ${state.cart.length?"":"disabled"}>Continuar pedido</button></div>`);bindCart()}
function bindCart(){document.querySelector("[data-close]").onclick=closeLayer;document.querySelectorAll("[data-cart-q]").forEach(b=>b.onclick=()=>{updateQty(b.dataset.key,Number(b.dataset.cartQ));openCart();updateCartBadges()});$("#clear-cart").onclick=()=>{state.cart=[];updateCartBadges();openCart();toast("Sacola limpa")};$("#checkout").onclick=openCheckout}
function neighborhoodOptions(city){return `<option value="">Selecione o bairro</option>${(DELIVERY_NEIGHBORHOODS[city]||[]).map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join("")}`}
function setDeliveryRequired(required){document.querySelectorAll("#address-field [data-delivery-required]").forEach(el=>el.required=required)}
function formatWhatsApp(input){const d=input.value.replace(/\D/g,"").slice(0,11);input.value=d.length>6?`(${d.slice(0,2)}) ${d.slice(2,7)}-${d.slice(7)}`:d.length>2?`(${d.slice(0,2)}) ${d.slice(2)}`:d.length?`(${d}`:"";input.setCustomValidity(d.length===11?"":"Informe um WhatsApp com DDD e 11 números.")}
function useCurrentLocation(){const btn=$("#use-location"),input=$("[name=maps_url]");if(!navigator.geolocation)return toast("Este aparelho não oferece localização.");btn.disabled=true;btn.textContent="Obtendo localização...";navigator.geolocation.getCurrentPosition(pos=>{input.value=`https://www.google.com/maps?q=${pos.coords.latitude.toFixed(6)},${pos.coords.longitude.toFixed(6)}`;input.setCustomValidity("");btn.textContent="✓ Localização confirmada";btn.classList.add("location-ready");btn.disabled=false;toast("Localização adicionada ao pedido")},()=>{btn.disabled=false;btn.textContent="Usar minha localização atual";toast("Permita o acesso à localização ou cole um link do Google Maps.")},{enableHighAccuracy:true,timeout:12000,maximumAge:60000})}
function openCheckout(){state.checkoutType="delivery";state.checkoutFeeCents=0;layer(`<div class="drawer-header"><button class="icon-btn" data-back aria-label="Voltar">←</button><h2>Finalizar pedido</h2></div><div class="drawer-content"><form class="checkout" id="checkout-form"><div class="segmented"><button type="button" class="active" data-type="delivery">Entrega</button><button type="button" data-type="pickup">Retirada</button></div><div class="field"><label>Seu nome *</label><input name="customer_name" required maxlength="80" autocomplete="name"></div><div class="field"><label>WhatsApp com DDD *</label><input name="phone" required inputmode="tel" autocomplete="tel" maxlength="15" placeholder="(87) 99999-9999"></div><fieldset class="delivery-fields" id="address-field"><legend>Endereço de entrega</legend><div class="address-grid city-neighborhood"><div class="field"><label>Cidade *</label><select name="city" data-delivery-required><option value="">Selecione a cidade</option><option value="Petrolina">Petrolina</option></select></div><div class="field"><label>Bairro *</label><input name="neighborhood" data-delivery-required maxlength="100" placeholder="Informe o bairro"></div></div><div class="field"><label>Rua / Avenida *</label><input name="street" data-delivery-required maxlength="160" autocomplete="address-line1" placeholder="Nome da rua ou avenida"></div><div class="address-grid house-details"><div class="field"><label>Número *</label><input name="house_number" data-delivery-required maxlength="20" autocomplete="address-line2" placeholder="Ex.: 60A"></div><div class="field"><label>Bloco <span class="optional">(opcional)</span></label><input name="block" maxlength="40" placeholder="Ex.: B"></div></div><div class="field"><label>Ponto de referência <span class="optional">(opcional)</span></label><input name="reference_point" maxlength="160" placeholder="Ex.: próximo à praça"></div><div class="field"><label>Complemento <span class="optional">(opcional)</span></label><input name="complement" maxlength="120" placeholder="Casa, apartamento, fundos..."></div><div class="field location-field"><label>Localização no Google Maps <span class="optional">(opcional)</span></label><input type="url" name="maps_url" maxlength="500" placeholder="Cole o link do Google Maps"><button type="button" class="secondary-btn location-btn" id="use-location">Usar minha localização atual</button><small>Use somente se quiser facilitar a entrega.</small></div></fieldset><div class="field"><label>Forma de pagamento *</label><select name="payment_method" required><option value="dinheiro">Dinheiro</option><option value="pix">Pix</option><option value="credito">Cartão de crédito</option><option value="debito">Cartão de débito</option></select></div><div class="field"><label>Observações gerais <span class="optional">(opcional)</span></label><textarea name="notes" maxlength="500" placeholder="Alguma informação para a acaiteria?"></textarea></div></form></div><div class="drawer-footer"><div class="subtotal-line"><span>Subtotal</span><span>${money(cartTotal())}</span></div><div class="subtotal-line" id="checkout-fee-row"><span>Taxa de entrega conforme bairro</span><span id="checkout-fee">${money(0)}</span></div><div class="cart-total"><span>Total</span><span id="checkout-total">${money(checkoutTotal())}</span></div><button class="primary-btn full" id="send-order">Enviar pedido</button></div>`);document.querySelector("[data-back]").onclick=openCart;const phone=$("[name=phone]"),neighborhood=$("[name=neighborhood]");phone.oninput=()=>formatWhatsApp(phone);neighborhood.oninput=updateCheckoutFee;$("#use-location").onclick=useCurrentLocation;document.querySelectorAll("[data-type]").forEach(b=>b.onclick=()=>{state.checkoutType=b.dataset.type;document.querySelectorAll("[data-type]").forEach(x=>x.classList.toggle("active",x===b));const delivery=state.checkoutType==="delivery";$("#address-field").classList.toggle("hidden",!delivery);setDeliveryRequired(delivery);$("#checkout-fee-row").classList.toggle("hidden",!delivery);updateCheckoutFee()});$("#send-order").onclick=submitOrder}
async function submitOrder(){const form=$("#checkout-form"),phone=$("[name=phone]");formatWhatsApp(phone);const neighborhoodSearch=$("#neighborhood-search"),neighborhoodValue=$("#neighborhood-value");if(state.checkoutType==="delivery"&&neighborhoodSearch&&neighborhoodValue&&!neighborhoodValue.value.trim())neighborhoodSearch.setCustomValidity("Selecione um bairro da lista para calcular a taxa.");const mapInput=$("[name=maps_url]");mapInput.setCustomValidity(mapInput.value&&!safeMapsUrl(mapInput.value)?"Informe um link válido do Google Maps ou deixe em branco.":"");if(!form.reportValidity())return;const fd=new FormData(form),paymentMethod=fd.get("payment_method"),needsChange=paymentMethod==="dinheiro"&&$("#checkout-needs-change")?.checked,cashValue=$("#checkout-cash-received")?.value||"",cashReceived=Math.max(0,Math.round(Number(String(cashValue).replace(/[^0-9,.-]/g,"").replace(/\./g,"").replace(",","."))*100)||0);if(needsChange&&cashReceived<checkoutTotal())return toast("O valor em dinheiro precisa ser igual ou maior que o total do pedido.");const fdPayload={branch_id:currentBranch(),customer_name:fd.get("customer_name"),phone:fd.get("phone"),city:fd.get("city"),neighborhood:fd.get("neighborhood"),street:fd.get("street"),house_number:fd.get("house_number"),block:fd.get("block"),reference_point:fd.get("reference_point"),complement:fd.get("complement"),maps_url:fd.get("maps_url"),payment_method:paymentMethod,change_for_cents:needsChange?cashReceived-checkoutTotal():null,notes:fd.get("notes"),order_type:state.checkoutType,items:state.cart.map(i=>({product_id:i.product.id,product_name:i.product.name,unit_price_cents:itemUnitPrice(i),quantity:i.quantity,complements:i.complements||[],notes:i.notes||""}))},btn=$("#send-order");btn.disabled=true;btn.textContent="Enviando...";try{const order=await api("/api/orders?branch="+currentBranch(),{method:"POST",body:JSON.stringify(fdPayload)}),completed={...fdPayload,...order,created_at:new Date().toISOString().replace("T"," ").replace("Z","")};state.lastOrder=completed;state.cart=[];updateCartBadges();showSuccess(completed)}catch(e){toast(e.message);btn.disabled=false;btn.textContent="Enviar pedido"}}
function showSuccess(order){rememberOrder(order.id);beginTracking(order.id,order.status);const message=customerOrderMessage(order),storePhone=state.catalog.settings.phone;layer(`<div class="drawer-header"><button class="icon-btn" data-close>×</button><h2>Pedido recebido</h2></div><div class="drawer-content"><div class="success-card"><div class="success-check">✓</div><h2>Agora é com a gente!</h2><p class="muted">Guarde o código para acompanhar o preparo.</p><div class="order-code">${esc(order.id)}</div><div class="timeline"><div class="timeline-row done"><i class="timeline-dot"></i>Pedido recebido</div><div class="timeline-row"><i class="timeline-dot"></i>Confirmação da acaiteria</div><div class="timeline-row"><i class="timeline-dot"></i>Preparo e entrega</div></div></div>${pixPaymentMarkup(order)}<a class="whatsapp-btn full" href="${esc(whatsappUrl(storePhone,message))}" target="_blank" rel="noopener noreferrer"><span class="whatsapp-logo">☎</span><span><strong>Enviar pedido pelo WhatsApp</strong><small>Notifique a acaiteria com o pedido preenchido</small></span></a>${notificationReminder()}</div><div class="drawer-footer"><button class="primary-btn full" data-track="${esc(order.id)}">Acompanhar pedido</button></div>`);document.querySelector("[data-close]").onclick=closeLayer;document.querySelector("[data-track]").onclick=e=>trackOrder(e.currentTarget.dataset.track);bindNotificationButton()}
function openTracking(){layer(`<div class="drawer-header"><button class="icon-btn" data-close>←</button><h2>Acompanhar pedido</h2></div><div class="drawer-content"><div class="field"><label>Código do pedido</label><input id="track-code" value="${esc(state.lastOrder?.id||"")}" placeholder="PED-..."></div><button class="primary-btn full" id="track-go">Consultar</button>${notificationReminder()}<div id="track-result"></div></div>`);document.querySelector("[data-close]").onclick=closeLayer;$("#track-go").onclick=()=>trackOrder($("#track-code").value);bindNotificationButton();if(state.lastOrder?.id)trackOrder(state.lastOrder.id)}
function trackingMarkup(o){const steps=o.order_type==="delivery"?["novo","confirmado","preparando","pronto","saiu_entrega","concluido"]:["novo","confirmado","preparando","pronto","concluido"];const at=steps.indexOf(o.status);const cancelled=o.status==="cancelado";return `<div class="panel tracking-card"><div class="tracking-head"><div><strong>${esc(o.id)}</strong><span>${esc(orderTypeLabel(o.order_type))}</span></div><strong>${money(o.total_cents)}</strong></div>${cancelled?`<div class="tracking-cancelled"><strong>Pedido cancelado.</strong>${o.cancel_reason?`<span>Motivo: ${esc(o.cancel_reason)}</span>`:`<span>Entre em contato com a acaiteria se precisar de ajuda.</span>`}</div>`:`<div class="timeline">${steps.map((s,i)=>`<div class="timeline-row ${i<=at?"done":""} ${s==="saiu_entrega"&&o.status==="saiu_entrega"?"current":""}"><i class="timeline-dot"></i><span>${statusLabel(s)}</span>${s==="saiu_entrega"&&o.status==="saiu_entrega"?"<strong>Seu pedido está a caminho!</strong>":""}</div>`).join("")}</div>`}<div class="tracking-items">${(o.items||[]).map(i=>`<span>${i.quantity}× ${esc(i.product_name)}</span>`).join("")}</div><small class="tracking-refresh">Atualização automática a cada 12 segundos</small></div>`}
async function trackOrder(code,background=false){if(!code){if(!background)toast("Informe o código do pedido");return}const normalized=String(code).trim();try{const o=await api(`/api/orders/${encodeURIComponent(normalized)}`);const previous=state.tracking.code===normalized?state.tracking.status:null;if(previous&&previous!==o.status)notifyOrderStatus(o);rememberOrder(o.id);beginTracking(o.id,o.status);state.tracking.status=o.status;if(!background&&!$("#track-result"))openTracking();if($("#track-result"))$("#track-result").innerHTML=trackingMarkup(o)}catch(e){if(!background)toast(e.message)}}
function openInfo(){const s=state.catalog.settings,rules=s.delivery_neighborhood_fees||[],fees=rules.length?`<div class="delivery-fee-public">${rules.map(rule=>`<div><span>${esc(rule.city)} • ${esc(rule.neighborhood)}</span><strong>${money(rule.fee_cents)}</strong></div>`).join("")}</div>`:'<p class="muted">Nenhuma taxa cadastrada no momento.</p>';layer(`<div class="drawer-header"><button class="icon-btn" data-close>←</button><h2>Bliss Açaiteria</h2></div><div class="drawer-content"><img class="store-logo" style="margin-bottom:18px" src="${JW_LOGO}" alt=""><h2>Informações da loja</h2><p><strong>Endereço</strong><br>${esc(s.address)}</p><p><strong>Telefone</strong><br><a href="tel:${s.phone.replace(/\D/g,"")}">${esc(s.phone)}</a></p><p><strong>Entrega</strong><br>${esc(eta(s.delivery_eta))} • confira as taxas antes de pedir</p>${s.delivery_surcharge_enabled?`<div class="fee-alert">${esc(s.delivery_surcharge_label||"Acréscimo temporário")} • +${Number(s.delivery_surcharge_percent||0)}%</div>`:""}<h3>Bairros e taxas de entrega</h3>${fees}<p><strong>Retirada</strong><br>${esc(eta(s.pickup_eta))}</p></div>`);document.querySelector("[data-close]").onclick=closeLayer}

function tableStatusLabel(status){return({novo:"Aguardando",confirmado:"Confirmado",preparando:"Em preparo",pronto:"Pronto",saiu_entrega:"Em atendimento"})[status]||"Ocupada"}
function tablesBoardMarkup(data,{admin=false}={}){const tables=data?.tables||[];return `<div class="tables-summary"><div><strong>${data?.available_count||0}</strong><span>Disponíveis</span></div><div><strong>${data?.occupied_count||0}</strong><span>Ocupadas</span></div><div><strong>${data?.table_count||0}</strong><span>Total de mesas</span></div></div>${tables.length?`<div class="tables-grid">${tables.map(table=>{const content=`<span class="table-dot"></span><strong>Mesa ${table.number}</strong><span>${table.occupied?tableStatusLabel(table.status):"Disponível"}</span>${admin&&table.occupied?`<small>${esc(table.order_id)}</small>`:""}`;return admin&&table.occupied?`<button type="button" class="table-card table-card-action occupied" data-table-order="${esc(table.order_id)}" aria-label="Abrir pedido da mesa ${table.number}">${content}</button>`:`<article class="table-card ${table.occupied?"occupied":"available"}">${content}</article>`}).join("")}</div>`:`<div class="empty table-empty">O proprietário ainda não configurou a quantidade de mesas.</div>`}`}
function publicTablesApp(){const data=state.tables.data;return `<main class="public-tables"><header class="tables-top"><img src="${JW_LOGO}" alt="Bliss Açaiteria"><div><strong>Bliss Açaiteria</strong><span>Painel de mesas</span></div><a href="/">Cardápio</a></header><section class="tables-hero"><div><span class="eyebrow">ATUALIZAÇÃO AO VIVO</span><h1>Mesas da casa</h1><p>Consulte quais mesas estão disponíveis antes de fazer seu pedido.</p></div><span class="tables-clock" id="tables-clock">${new Date().toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"})}</span></section>${tablesBoardMarkup(data)}</main>`}
async function loadPublicTables(){state.tables.data=await api("/api/tables");if(location.pathname==="/mesas"){$("#app").innerHTML=publicTablesApp()}}
function startPublicTables(){document.title="Bliss Açaiteria — Mesas";loadPublicTables().catch(e=>{$("#app").innerHTML=`<div class="boot"><div class="boot-mark">!</div><h2>Não foi possível carregar as mesas</h2><p>${esc(e.message)}</p><button class="primary-btn" onclick="location.reload()">Tentar novamente</button></div>`});clearInterval(state.tables.timer);state.tables.timer=setInterval(()=>loadPublicTables().catch(()=>{}),10000)}

// Painel do proprietário
function adminLayout(content,title){return `<div class="admin-shell"><aside class="admin-side"><div class="admin-brand"><img src="${JW_LOGO}" alt="Logo Bliss Açaiteria"><div><strong>Bliss Açaiteria</strong><span>Gestão do negócio</span></div></div><nav class="admin-nav">${adminNavButtons()}</nav><div class="admin-side-footer"><button class="secondary-btn full" data-admin-action="open-store">Ver cardápio público</button></div></aside><main class="admin-main"><header class="admin-topbar"><h1>${esc(title)}</h1><div class="admin-top-actions"><span class="live-pill">● Sistema online</span><button class="secondary-btn" data-admin-action="logout">Sair</button></div></header><div class="admin-content">${content}</div></main><nav class="admin-mobile-nav">${adminNavButtons()}</nav></div><div id="layer"></div>`}
function adminNavButtons(){return [{v:"orders",i:"▤",l:"Pedidos",s:"Pedidos"},{v:"pos",i:"＋",l:"Balcão",s:"Balcão"},{v:"availability",i:"◷",l:"Abrir / fechar",s:"Loja"},{v:"tables",i:"▦",l:"Mesas",s:"Mesas"},{v:"revenue",i:"▥",l:"Faturamento",s:"Fatur."},{v:"products",i:"▤",l:"Produtos",s:"Produtos"},{v:"settings",i:"⚙",l:"Configurações",s:"Config."}].map(x=>`<button class="${state.admin.view===x.v?"active":""}" data-admin-view="${x.v}"><span class="admin-nav-icon">${x.i}</span><span class="nav-full">${x.l}</span><span class="nav-short">${x.s}</span></button>`).join("")}
function loginPage(){return `<div class="login-page"><form class="login-card" id="login-form"><img class="login-logo" src="${JW_LOGO}" alt="Logo Açailandia PE"><h1>Painel da Açailandia PE</h1><p>Digite o PIN administrativo para gerenciar pedidos, cardápio e vendas no balcão.</p><label class="sr-only" for="pin">PIN</label><input class="pin-input" id="pin" name="pin" maxlength="32" autocomplete="current-password" placeholder="Digite o PIN"><button class="primary-btn full">Entrar no painel</button></form></div>`}
async function startAdmin(){document.title="Açailandia PE — Gestão";try{const data=await api("/api/admin/orders");state.admin.logged=true;state.admin.orders=data.orders;state.admin.visits=data.visits||{today:0,total:0};renderAdmin();startAdminRefresh()}catch{$("#app").innerHTML=loginPage();$("#login-form").onsubmit=adminLogin}}
async function adminLogin(e){e.preventDefault();const btn=e.currentTarget.querySelector("button");btn.disabled=true;try{await api("/api/admin/login",{method:"POST",body:JSON.stringify({pin:$("#pin").value})});state.admin.logged=true;await loadAdminOrders();renderAdmin();startAdminRefresh()}catch(err){toast(err.message);btn.disabled=false}}
