  const delivery=order.order_type==="delivery";
  const addressFields=delivery?`<section class="edit-order-details"><strong>Local de entrega</strong><div class="compact-field"><div class="field"><label>Cidade</label><select id="cashier-edit-city"><option value="Petrolina" ${order.city==="Petrolina"?"selected":""}>Petrolina</option><option value="Juazeiro" ${order.city==="Juazeiro"?"selected":""}>Juazeiro</option></select></div><div class="field"><label>Bairro</label><input id="cashier-edit-neighborhood" value="${esc(order.neighborhood||"")}" required></div></div><div class="compact-field"><div class="field"><label>Rua / avenida</label><input id="cashier-edit-street" value="${esc(order.street||"")}"></div><div class="field"><label>Número</label><input id="cashier-edit-number" value="${esc(order.house_number||"")}"></div></div><div class="compact-field"><div class="field"><label>Referência</label><input id="cashier-edit-reference" value="${esc(order.reference_point||"")}"></div><div class="field"><label>Complemento</label><input id="cashier-edit-complement" value="${esc(order.complement||"")}"></div></div><div class="field"><label>Link do mapa</label><input id="cashier-edit-maps" value="${esc(order.maps_url||"")}" inputmode="url" placeholder="https://maps.google.com/..."></div></section>`:`<p class="muted">Pedido para retirada: não há local de entrega para alterar.</p>`;
  layer(`<div class="drawer-header"><button class="icon-btn" data-close>×</button><div><h2>Editar pedido</h2><span class="muted">${esc(order.id)} • ${esc(cashier.name)}</span></div></div><form class="drawer-content order-editor" id="cashier-order-edit-form"><section class="edit-order-details"><strong>Forma de pagamento</strong><div class="field"><label>Pagamento</label><select id="cashier-edit-payment">${paymentOptions}</select></div></section>${addressFields}</form><div class="drawer-footer"><button class="primary-btn full" id="cashier-save-order-edit">Salvar alterações</button></div>`,"drawer admin-order-drawer");
  document.querySelector("[data-close]").onclick=closeLayer;
  $("#cashier-save-order-edit").onclick=async()=>{const form=$("#cashier-order-edit-form");if(!form.reportValidity())return;const button=$("#cashier-save-order-edit"),details={order_type:order.order_type,payment_method:$("#cashier-edit-payment").value};if(delivery)Object.assign(details,{city:$("#cashier-edit-city").value,neighborhood:$("#cashier-edit-neighborhood").value,street:$("#cashier-edit-street").value,house_number:$("#cashier-edit-number").value,reference_point:$("#cashier-edit-reference").value,complement:$("#cashier-edit-complement").value,maps_url:$("#cashier-edit-maps").value});button.disabled=true;try{await api(`/api/cashier/orders/${encodeURIComponent(id)}/details`,{method:"PATCH",body:JSON.stringify(details)});await refreshCashier();closeLayer();renderCashierPanel();toast("Pedido atualizado")}catch(error){toast(error.message);button.disabled=false}};
