document.addEventListener("click",async event=>{const button=event.target.closest("[data-reprint-order]");if(!button)return;event.preventDefault();event.stopPropagation();button.disabled=true;try{await api(`/api/admin/orders/${encodeURIComponent(button.dataset.reprintOrder)}/reprint`,{method:"POST"});toast("Comanda reenviada para o caixa e a cozinha")}catch(error){toast(error.message);button.disabled=false}},true);
posView=()=>originalPosView().replace(/<label class="check-row"><input type="checkbox" id="pos-waiter-fee"[\s\S]*?<\/label>/,"").replace('<option value="pago">Pago</option><option value="aberto">Pagamento em aberto</option>','<option value="aberto" selected>Pagamento em aberto</option>').replace('<label>Observações</label>','<label>Observações para a cozinha</label>').replace('Registrar pedido','Abrir comanda');
finishPos=async()=>{const fd=new FormData($("#pos-form")),btn=$("#pos-finish");if(fd.get("order_type")==="pickup"&&!fd.get("table_number"))return toast("Selecione uma mesa disponível.");btn.disabled=true;try{const order=await api("/api/admin/orders",{method:"POST",body:JSON.stringify({customer_name:fd.get("customer_name"),table_number:fd.get("table_number"),order_type:fd.get("order_type"),payment_method:fd.get("payment_method"),payment_status:"aberto",notes:fd.get("notes"),items:state.admin.posCart.map(i=>({product_id:i.product.id,quantity:i.quantity,complements:i.complements||[],notes:i.notes||""}))})});state.admin.posCart=[];state.admin.posWaiterFee=false;toast(`Comanda ${order.id} aberta${order.table_number?` na mesa ${order.table_number}`:""}`);state.admin.view="orders";await loadAdminOrders();renderAdmin()}catch(e){toast(e.message);btn.disabled=false}};
function openPaymentSettlement(id){const order=state.admin.orders.find(item=>item.id===id);if(!order)return;const config=state.catalog?.settings||{};if(order.payment_status!=="aberto"){api(`/api/admin/orders/${encodeURIComponent(id)}/payment`,{method:"PATCH",body:JSON.stringify({payment_status:"aberto"})}).then(async()=>{await loadAdminOrders();renderAdmin();toast("Pagamento reaberto")}).catch(e=>toast(e.message));return}const feeAllowed=order.channel==="counter"&&config.waiter_fee_enabled;layer(`<div class="drawer-header"><button class="icon-btn" data-close>×</button><h2>Fechar conta</h2></div><form class="drawer-content" id="settle-payment-form"><p class="muted">Comanda ${esc(order.id)}${order.table_number?` • Mesa ${order.table_number}`:""}</p><div class="field"><label>Forma de pagamento</label><select name="payment_method"><option value="dinheiro" ${order.payment_method==="dinheiro"?"selected":""}>Dinheiro</option><option value="pix" ${order.payment_method==="pix"?"selected":""}>Pix</option><option value="credito" ${order.payment_method==="credito"?"selected":""}>Cartão de crédito</option><option value="debito" ${order.payment_method==="debito"?"selected":""}>Cartão de débito</option></select></div>${feeAllowed?`<label class="check-row"><input type="checkbox" name="apply_waiter_fee"><span><strong>Adicionar taxa de garçom (${config.waiter_fee_percent}%)</strong><small>Escolha somente se o cliente aceitar pagar a taxa.</small></span></label>`:""}</form><div class="drawer-footer"><button class="primary-btn full" id="confirm-payment">Confirmar pagamento</button></div>`,`drawer admin-order-drawer`);document.querySelector("[data-close]").onclick=closeLayer;$("#confirm-payment").onclick=async()=>{const form=$("#settle-payment-form"),button=$("#confirm-payment"),data=new FormData(form);button.disabled=true;try{const result=await api(`/api/admin/orders/${encodeURIComponent(id)}/payment`,{method:"PATCH",body:JSON.stringify({payment_status:"pago",payment_method:data.get("payment_method"),apply_waiter_fee:data.get("apply_waiter_fee")==="on"})});await loadAdminOrders();closeLayer();renderAdmin();toast(result.waiter_fee_cents?"Pagamento confirmado com taxa de garçom":"Pagamento confirmado")}catch(e){toast(e.message);button.disabled=false}}}
document.addEventListener("click",event=>{const button=event.target.closest("[data-payment-order]");if(!button)return;event.preventDefault();event.stopPropagation();openPaymentSettlement(button.dataset.paymentOrder)},true);


